#[test]
fn every_rack_effect_at_every_rate_and_block() {
    let names: Vec<_> = catalogue().iter().map(|e| e.descriptor.id).collect();
    matrix::run(&names, ALLOW, |name, rate, block| {
        let mut rack = Rack::new();
        rack.push(Box::new(PrismEffect::new(name, rate).unwrap()));
        rack.reserve_mix(block * 2);
        let input = matrix::sine(rate);
        let mut stereo: Vec<_> = input.iter().flat_map(|&x| [x, x]).collect();
        for chunk in stereo.chunks_mut(block * 2) {
            rack.process(chunk, 2, rate);
        }
        assert_eq!(rack.tripped(), 0, "{name}/{rate}/{block}");
        stereo.chunks_exact(2).map(|s| s[0]).collect()
    });
}
